io.on('connection', (socket) => {
  socket.on('webrtc_offer', async ({ consultationId, sdpOffer }) => {
    const session = await ConsultationSession.findByPk(consultationId);
    if (!session || (session.patientId !== socket.data.userId && session.doctorId !== socket.data.userId)) {
      return socket.emit('error', { message: 'Not authorized for this medical consultation' });
    }
    socket.to(`consultation:${consultationId}`).emit('incoming_sdp_offer', {
      fromUser: socket.data.userId,
      sdpOffer
    });
  });
});
